// Room: Drying lean-to (interior designer's part, box [15,1,18,18,3,24]).
// Floor grid from `mcd plan`, origin [15, 1, 18] (x 15..18, z 18..24). Layout:
//  - focal piece: two candle racks on the east side (x=17): dark-oak fence uprights with a closed trapdoor shelf, and
//    a lit white_candle cluster on each shelf; the lanterns hang over them, so this is the brightest corner.
//  - tallow barrels at the back-west (x=15, z=18..19) with lit candles on top.
//  - the lane x=16 stays clear from the back door (16,2..3,18) to the south opening; x=18 stays clear to the east.
// Light: 2 hanging lanterns from the lean-to slab roof (y=4), 4 lit candle clusters.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  b: "barrel",
  F: "dark_oak_fence",
  T: ["dark_oak_trapdoor", { facing: "north", half: "top", open: "false", powered: "false", waterlogged: "false" }],
  C: ["white_candle", { candles: "3", lit: "true", waterlogged: "false" }],
  c: ["white_candle", { candles: "2", lit: "true", waterlogged: "false" }],
  L: ["lantern", { hanging: "true", waterlogged: "false" }],
};

// y=1 (floor row), y=2 (candles), y=3 (lanterns); rows run along +z from z=18, columns along +x from x=15
const ROWS = [
  [ // y=1
    "b...", // z18
    "b.F.", // z19
    "..T.", // z20
    "..F.", // z21
    "..F.", // z22
    "..T.", // z23
    "..F.", // z24
  ],
  [ // y=2
    "c...", // z18
    "C...", // z19
    "..C.", // z20
    "....", // z21
    "....", // z22
    "..C.", // z23
    "....", // z24
  ],
  [ // y=3
    "....", // z18
    "....", // z19
    "..L.", // z20
    "....", // z21
    "....", // z22
    "..L.", // z23
    "....", // z24
  ],
];

export function build(g) {
  layers(g, [15, 1, 18], LEGEND, ROWS);
}

